export type Ticket = { title: string; priority: "low" | "normal" | "high"; hours: number };
export type Completion = { text: string; inputTokens: number; outputTokens: number };
export type Complete = { (prompt: string, maxTokens: number): Promise<Completion> };

export function parseTicket(raw: string): Ticket {
    // TODO: check every field before returning the parsed value
    return JSON.parse(raw) as Ticket;
}

export async function extractTicket(note: string, complete: Complete): Promise<Ticket> {
    let prompt = "Extract a ticket from this note:\n" + note;
    while (true) {
        const result = await complete(prompt, 10000);
        try {
            return parseTicket(result.text);
        } catch {
            prompt = prompt + "\nTry again.";
        }
    }
}

